<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Document\ThemeVersion\Application\Usecase\List;

use Psr\EventDispatcher\EventDispatcherInterface;
use Throwable;
use Civi\Lughauth\Shared\Security\Allow;
use Civi\Lughauth\Shared\Exception\UnauthorizedException;
use Civi\Lughauth\Features\Document\ThemeVersion\Application\Service\Visibility\ThemeVersionVisibilityService;
use Civi\Lughauth\Features\Document\ThemeVersion\Domain\Gateway\ThemeVersionReadGateway;
use Civi\Lughauth\Features\Document\ThemeVersion\Domain\Gateway\ThemeVersionFilter;
use Civi\Lughauth\Features\Document\ThemeVersion\Domain\Gateway\ThemeVersionCursor;
use Civi\Lughauth\Features\Document\ThemeVersion\Domain\Gateway\ThemeVersionAttributesSlide;
use Civi\Lughauth\Shared\Observability\LoggerAwareTrait;
use Civi\Lughauth\Shared\Observability\TracerAwareTrait;

class ThemeVersionListUsecase
{
    use LoggerAwareTrait;
    use TracerAwareTrait;

    public function __construct(
        private readonly EventDispatcherInterface $dispatcher,
        private readonly ThemeVersionVisibilityService $visibility,
        private readonly ThemeVersionReadGateway $reader
    ) {
    }

    public function allowList(): Allow
    {
        $this->logDebug("Check allow of list usecase for Theme version");
        $span = $this->startSpan("Check allow of list usecase for Theme version");
        try {
            $result = $this->dispatcher->dispatch(new ThemeVersionListAllowDecision(Allow::allowed('list', 'Allowed to list by default')));
            return $result->getAllow();
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    public function count(ThemeVersionFilter $filter): int
    {
        $this->logDebug("Run list usecase for Theme version");
        $span = $this->startSpan("Run list usecase for Theme version");
        try {
            $allow = $this->allowList();
            if (!$allow->allowed) {
                throw new UnauthorizedException($allow->reason ?? 'Not allowed to list Theme version');
            }
            return $this->visibility->countVisibles($filter);
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    public function list(ThemeVersionFilter $filter, ?ThemeVersionCursor $cursor = null): ThemeVersionAttributesSlide
    {
        $this->logDebug("Run list usecase for Theme version");
        $span = $this->startSpan("Run list usecase for Theme version");
        try {
            $allow = $this->allowList();
            if (!$allow->allowed) {
                throw new UnauthorizedException($allow->reason ?? 'Not allowed to list');
            }
            $slide = $this->visibility->listVisibles($filter, $cursor);
            return new ThemeVersionAttributesSlide($slide->nextCursor(), array_map(fn ($item) => $this->visibility->copyWithHidden($this->visibility->prepareVisibleData($item)), $slide->values()));
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
}
